(()=>{document.body.replaceChildren();document.body.style.cssText='margin:0';const sheet=document.createElement('style');sheet.textContent='.sample{padding-left:20px;padding-right:20px}@media (width <= 720px){.sample{padding-left:5px;padding-right:5px}}@media screen and (min-width:800px){@media (height>10px){.sample{border-top:2px solid}}}@supports (display:madeup){.sample{padding-left:99px}}';document.head.append(sheet);const root=document.createElement('div');root.style.cssText='width:400px;position:fixed;left:0;top:0;font:16px "Times New Roman";line-height:20px';root.innerHTML='<div class="sample" style="box-sizing:border-box;width:200px;margin:10px auto"><p style="margin:0">alpha beta gamma delta epsilon zeta eta theta iota kappa lambda</p><div><input type="hidden" style="display:block!important"></div><noscript>ignored text</noscript><div id="target"></div></div>';document.body.append(root);const sample=root.firstElementChild,rect=e=>{const r=e.getBoundingClientRect();return [r.x,r.y,r.width,r.height]},out={rects:[sample,...sample.children].map(rect),media:['(width <= 720px)','(720px < width)','(1px < width < 10000px)','screen and (min-width:800px)','not screen','(orientation:landscape)','(width:0px), (height>1px)','not (width:1px)'].map(q=>matchMedia(q).matches)};out.margins=[getComputedStyle(sample).marginLeft,getComputedStyle(sample).marginRight];out.hiddenDisplay=getComputedStyle(sample.querySelector('input')).display;const getter=window.matchMedia,supports=CSS.supports;window.matchMedia=()=>{throw Error('author matchMedia')};CSS.supports=()=>{throw Error('author supports')};try{out.privateRead=getComputedStyle(sample).paddingLeft}catch(e){out.privateRead=e.name}window.matchMedia=getter;CSS.supports=supports;const frame=document.createElement('iframe');frame.style.cssText='width:320px;height:200px;border:0';root.append(frame);out.frame=[frame.contentWindow.matchMedia('(max-width:400px)').matches];frame.style.width='640px';out.frame.push(frame.contentWindow.matchMedia('(max-width:400px)').matches);frame.remove();root.innerHTML='<div style="height:10px;margin-bottom:20px"></div><div></div><div style="height:10px;margin-top:30px"></div>';out.emptyCollapse=[...root.children].map(rect);root.remove();sheet.remove();return out})()